def solve(g):
    o=[[0]*len(g[0]) for _ in range(len(g))]
    H=len(g); W=len(g[0])
    # find bands: split rows into groups separated by all-5 row; treat rows 1-3 & 11-13 as the object bands here
    # collect objects (connected components) per color; drop color 2; keep one representative per distinct shape
    from collections import defaultdict
    seen=set(); comps=[]
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v!=0 and v!=5 and (r,c) not in seen:
                # flood fill
                st=[(r,c)]; comp=[]
                seen.add((r,c))
                while st:
                    y,x=st.pop()
                    comp.append((y,x)); 
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==v and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                comps.append((v,comp))
    shapec=defaultdict(list)
    for v,comp in comps:
        r0=min(r for r,c in comp); c0=min(c for r,c in comp)
        shapec[(tuple(sorted((r-r0,c-c0) for r,c in comp))),v].append(comp)
    kept=[]
    for key in shapec:
        sh,v=key; cs=shapec[key]
        # keep the LAST occurrence of each distinct shape (matches demos: d1 kept bottom ring)
        kept.append(cs[-1]);  # will replace
    kept=[]
    for (sh,v),cs in shapec.items():
        if v!=2: kept.append(cs[-1])
    # stack: sort by original row
    kept.sort(key=lambda cc: min(r for r,c in cc))
    tops=[min(r for r,c in cc) for cc in kept]
    # vertical start: use the demo-derived heuristic = first dropped object's top +1 if first dropped in top band else ... hard; pick: start rows based on input top
    # safer: replicate vertical placement from each demo's pattern: out_top = in_top - 1 when... let's just place consecutively from first kept top with same spacing (3) and verify later by checking demo reconstruction
    base=tops[0] if kept else 0
    out=[[0]*W for _ in range(3*len(kept))]
